from PIL import Image
img = Image.open('/opt/exam/grader/golden.png')
w, h = img.size
# Find very bright pixels (pins are bright white/silver)
bright = []
for y in range(h):
    for x in range(w):
        r, g, b = img.getpixel((x, y))
        if r > 200 and g > 200 and b > 200:
            bright.append((x, y))
print('Count of bright pixels:', len(bright))
# Cluster bright pixels
clusters = []
for p in bright:
    matched = False
    for c in clusters:
        # if close to cluster mean
        mx = sum(x for x, y in c) / len(c)
        my = sum(y for x, y in c) / len(c)
        if (p[0] - mx)**2 + (p[1] - my)**2 < 400:
            c.append(p)
            matched = True
            break
    if not matched:
        clusters.append([p])
for i, c in enumerate(clusters):
    if len(c) > 5:
        print(f'Cluster {i}: len={len(c)}, cx={sum(x for x, y in c)/len(c):.2f}, cy={sum(y for x, y in c)/len(c):.2f}')
"

